typedef struct {
    int *data;
    int size;
    int capacity;
    int (*cmp)(int a, int b);
} Heap;

static int maxCmp(int a, int b) { return a > b; }
static int minCmp(int a, int b) { return a < b; }

Heap* heapCreate(int capacity, int (*cmp)(int, int)) {
    Heap *h = (Heap*)malloc(sizeof(Heap));
    h->data = (int*)malloc(sizeof(int)*capacity);
    h->size = 0;
    h->capacity = capacity;
    h->cmp = cmp;
    return h;
}

void heapFree(Heap *h) {
    free(h->data);
    free(h);
}

void heapSwap(int *a, int *b) {
    int t = *a; *a = *b; *b = t;
}

void heapPush(Heap *h, int val) {
    if (h->size == h->capacity) return; // Should not happen if capacity is enough
    h->data[h->size++] = val;
    int i = h->size - 1;
    while (i > 0) {
        int p = (i-1)/2;
        if (h->cmp(h->data[i], h->data[p])) {
            heapSwap(&h->data[i], &h->data[p]);
            i = p;
        } else break;
    }
}

void heapifyDown(Heap *h, int i) {
    int size = h->size;
    while (1) {
        int left = 2*i + 1;
        int right = 2*i + 2;
        int best = i;
        if (left < size && h->cmp(h->data[left], h->data[best])) best = left;
        if (right < size && h->cmp(h->data[right], h->data[best])) best = right;
        if (best == i) break;
        heapSwap(&h->data[i], &h->data[best]);
        i = best;
    }
}

